wint_t CDECL btowc(int c)
{
    unsigned char letter = c;
    wchar_t ret;

    if(c == EOF)
        return WEOF;
    if(!get_locinfo()->lc_codepage)
        return c & 255;
    if(!MultiByteToWideChar(get_locinfo()->lc_codepage,
                MB_ERR_INVALID_CHARS, (LPCSTR)&letter, 1, &ret, 1))
        return WEOF;

    return ret;
}

